def shift_down(g):
    g=[r[:] for r in g]
    H=len(g);W=len(g[0])
    for c in range(W):
        col=[g[r][c] for r in range(H)]
        cnt=sum(1 for x in col if x!=0)
        stack=[x for x in col if x==0]+list(reversed([x for x in col if x!=0]))
        for r,x in enumerate(stack):
            g[r][c]=x
    return g
