            if g[r][c]!=bg and max(comps_of(g,g[r][c]))<=2:
                nb=[g[x][y] for x in range(max(0,r-1),min(len(g),r+2))
                     for y in range(max(0,c-1),min(len(g[0]),c+2)) if (x,y)!=(r,c)]
                o[r][c]=Counter(nb).most_common(1)[0][0]
    return o
for i in range(1,9):
    gi=G[f'Demo pair {i} input']; go=np.array(G[f'Demo pair {i} output'])
    print(i, np.array_equal(solve(gi),go))
